mapper.insert:

	select concat(
		'N_', date_format(now(), '%y%m'), '_',
		LPAD(
		   ifnull(
				(select cast(substring(max(notice_no), 8, 4) as unsigned ) +1
				   from seinfo_notice
				  where notice_no like concat('N_', date_format(now(), '%y%m'), '_%')
				),
				1
			), 4, '0'
		)
	)


insert into seinfo_notice
(	 notice_type
	,notice_no
	,notice_title
	,notice_contents
	,inquire_cnt
	,mfile_group_id
	,reg_dt
	,reg_user_id
	,mod_dt
	,mod_user_id
) value (
	'N'
	,#{noticeNo}
	,left(#{noticeTitle}, 100)
	,#{noticeContents}
	,0
	,#{fileGrpId}
	,NOW()
	,#{userId}
	,NOW()
	,#{userId}
)

mapper.update:
update seinfo_notice
   set  notice_title 	= left(#{noticeTitle}, 100)
	  , notice_contents = #{noticeContents}
	  , mfile_group_id	= #{fileGrpId}
	  , mod_dt 			= now()
	  , mod_user_id		= #{userId}
 where notice_no = #{noticeNo}
   and notice_type = 'N'

update seinfo_notice
   set inquire_cnt = #{inquireCnt}
 where notice_no = #{noticeNo}
   and notice_type = 'N'
